//----------------------------------------------------------------------------------------------------
// Image — <img> element whose src may be a URL, binary data, or a Promise of either
//
// Binary sources become object URLs revoked on finalize, so callers can display fetched /
// generated bytes without managing URL lifetime.
//
// - Image : component({ src, className, style, designs, ...rest }) — src: string | Blob |
//           ArrayBuffer(View) | Promise; className / style decorate the container (fills the
//           host by default); designs: { image? } — a Design ({ className?, style? }) for the
//           <img> (object-fit etc.); rest members (alt, loading, …) pass through to the <img>;
//           returns { get container }
//
// Usage: xnew(xbasics.Image, { src: './background.jpg', className: 'absolute inset-0 size-full', designs: { image: { style: 'object-fit: cover;' } } });
//----------------------------------------------------------------------------------------------------

import { xnew } from '../../core/xnew';
import { Container } from './Container';
import { Design } from '../design';

type ImageSource = string | Blob | ArrayBuffer | ArrayBufferView<ArrayBuffer>;

export function Image(unit: xnew.Unit,
    { src, className = '', style = '', designs = {}, ...others }:
    { src: ImageSource | Promise<ImageSource>, className?: string, style?: string, designs?: { image?: Design }, [key: string]: any }
) {
    // the default size is pending (fills the host for now)
    xnew.extend(Container, {
        base: 'box-sizing: border-box; width: 100%; height: 100%;',
        className, style,
    });

    const cls = xnew.css({
        // fills the container; object-fit is left to designs (browser default: fill)
        image: {
            layer: 'base',
            body: `
                box-sizing: border-box; display: block; width: 100%; height: 100%;
            `,
        },
    });

    xnew.nest({ tag: 'img', className: `${cls.image} ${designs.image?.className ?? ''}`, style: designs.image?.style, ...others });
    const element = unit.element as HTMLImageElement;

    let objectURL: string | null = null;
    function apply(value: ImageSource): void {
        if (typeof value === 'string') {
            element.src = value;
        } else {
            objectURL = URL.createObjectURL(value instanceof Blob ? value : new Blob([value]));
            element.src = objectURL;
        }
    }
    if (src instanceof Promise) {
        xnew.promise(src).then(apply);
    } else {
        apply(src);
    }

    unit.on('finalize', () => {
        if (objectURL !== null) {
            URL.revokeObjectURL(objectURL);
        }
    });
}
